<?php
$sql='SELECT h.criado_em,h.acao,h.observacao,r.id AS reserva_id,u.nome AS usuario,e.nome AS equipamento FROM historico_reservas h INNER JOIN reservas r ON r.id=h.reserva_id INNER JOIN usuarios u ON u.id=h.usuario_id INNER JOIN equipamentos e ON e.id=r.equipamento_id';if(!admin())$sql.=' WHERE r.usuario_id='.(int)$_SESSION['id'];$sql.=' ORDER BY h.id DESC';$rows=$conn->query($sql);
?><h1>Histórico</h1><table><tr><th>Data</th><th>Reserva</th><th>Usuário</th><th>Equipamento</th><th>Ação</th><th>Observação</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=h($r['criado_em'])?></td><td><?=h($r['reserva_id'])?></td><td><?=h($r['usuario'])?></td><td><?=h($r['equipamento'])?></td><td><?=h($r['acao'])?></td><td><?=h($r['observacao'])?></td></tr><?php endwhile;?></table>
